INSERT INTO `lectures` VALUES (1,'Lecture 1 - Foundations of Public Health','Comprehensive introduction to the history, evolution, and core concepts of public health and community organizing.',1,'2026-09-05 16:33:01','2026-09-05 16:33:01'),(2,'Lecture 2 - Human Behavior and Community Health Education','Exploring the psychological and social factors that influence health behaviors, and strategies for community health education.',1,'2026-09-05 16:33:01','2026-09-05 16:33:01'),(3,'Lecture 3 - First Aid and Personal Wellness','A guide to understanding stress, maintaining personal wellness, recognizing shock, and performing vital first aid such as CPR.',1,'2026-09-05 16:33:02','2026-09-05 16:33:02'),(4,'Lecture 4 - Communicable Disease Control','Understanding the chain of infection, communicable disease models, and levels of prevention and eradication.',1,'2026-09-05 16:33:02','2026-09-05 16:33:02'),(5,'Lecture 5 - Community Water, Waste Management, and Sewage Disposal','A comprehensive guide to environmental health focusing on water sources, treatment, waste management, and sewage disposal.',1,'2026-09-05 16:33:03','2026-09-05 16:33:03'),(6,'Lecture 6 - Residential, Occupational, and Recreational Environment','A guide to environmental health protection focusing on housing quality, workplace safety, and recreational areas.',1,'2026-09-05 16:33:03','2026-09-05 16:33:03'),(7,'Lecture 7 - Vector and Zoonosis, Control of Air, Radiation, and Noise Pollution','Detailed look at zoonotic diseases, vectors, and environmental pollution including air, noise, and radiation.',1,'2026-09-05 16:33:03','2026-09-05 16:33:03'),(8,'Lecture 8 - Disaster Control Management','Understanding disaster risks, vulnerability, incident command systems, and emergency response.',1,'2026-09-05 16:33:04','2026-09-05 16:33:04'),(9,'Lecture 9 - Health Resources and Services, International and National Health Services','Exploration of global and local healthcare structures, international health organizations, and the Philippine healthcare delivery system.',1,'2026-09-05 16:33:04','2026-09-05 16:33:04'),(10,'Lecture 1 - The Cell','Human Histology: Cell Structure, Membranous and Nonmembranous Organelles, and the Nucleus.',0,'2026-09-05 16:33:05','2026-09-05 16:33:05'),(11,'Lecture 2 - Epithelium','Human Histology: Epithelial Tissue, Classification, Specializations, and Glands.',0,'2026-09-05 16:33:05','2026-09-05 16:33:05'),(12,'Lecture 3 - Connective Tissue','Human Histology: Connective Tissues, Fibers, Extracellular Matrix, and Connective Tissue Cells.',0,'2026-09-05 16:33:05','2026-09-05 16:33:05');
/*!40000 ALTER TABLE `lectures` ENABLE KEYS */;
